<?php
namespace Database\Seeders;
use App\Models\User; use Illuminate\Database\Console\Seeds\WithoutModelEvents; use Illuminate\Database\Seeder;
class DatabaseSeeder extends Seeder { use WithoutModelEvents; public function run(): void { User::updateOrCreate(['email'=>env('ADMIN_EMAIL','admin@example.com')],['name'=>env('ADMIN_NAME','Admin'),'password'=>env('ADMIN_PASSWORD','password'),'role'=>'admin']);$customers=[\App\Models\Customer::firstOrCreate(['email'=>'customer@example.com'],['name'=>'Acme Retail']),\App\Models\Customer::firstOrCreate(['email'=>'second@example.com'],['name'=>'Northwind Ltd']),\App\Models\Customer::firstOrCreate(['email'=>'third@example.com'],['name'=>'Bharat Traders'])];$supplier=\App\Models\Supplier::firstOrCreate(['email'=>'supplier@example.com'],['name'=>'Global Supplies']);\App\Models\Product::firstOrCreate(['name'=>'Consulting'],['type'=>'service','unit_price'=>150,'tax_rate'=>18]);\App\Models\Product::firstOrCreate(['name'=>'Office equipment'],['type'=>'product','unit_price'=>500,'tax_rate'=>18]);$budget=\App\Models\Budget::firstOrCreate(['name'=>'Operations '.now()->year],['period_type'=>'yearly','category'=>'Operations','amount'=>10000,'period_start'=>now()->startOfYear(),'period_end'=>now()->endOfYear()]);foreach(range(0,8) as $index){$date=now()->subMonths($index%8)->startOfMonth()->addDays(5);$due=$index%3===1?now()->addDays(30):($index%3===0?$date->copy()->addDays(30):$date->copy()->subDays(5));$invoice=\App\Models\SalesInvoice::create(['invoice_number'=>'SEED-S-'.$index,'customer_id'=>$customers[$index%3]->id,'issue_date'=>$date,'due_date'=>$due,'subtotal'=>1000,'tax_amount'=>0,'total'=>1000,'status'=>'Pending']);$invoice->items()->create(['description'=>'Seed consulting','quantity'=>1,'unit_price'=>1000,'tax_rate'=>0,'line_total'=>1000]);if($index%3===0){$invoice->payments()->create(['payment_date'=>$date,'amount'=>1000,'method'=>'bank']);}$invoice->refreshStatus();\App\Models\PurchaseInvoice::create(['invoice_number'=>'SEED-P-'.$index,'supplier_id'=>$supplier->id,'issue_date'=>$date,'due_date'=>$date->copy()->addDays(30),'subtotal'=>500,'tax_amount'=>0,'total'=>500,'status'=>'Pending']);\App\Models\Expense::create(['budget_id'=>$budget->id,'expense_date'=>$date,'amount'=>($index+1)*25,'description'=>'Seed '.$index,'category'=>['Marketing','Travel','Software','Operations'][$index%4]]);}} }
